69: export function getErrorRateChart({
70:   indexes,
71:   filters,
72:   metadataFields,
73: }: {
74:   indexes: string;
75:   filters: string[];
76:   metadataFields: string[];
77: }): TraceChart | null {
78:   try {
79:     const query = getBaseTraceQuery({ indexes, filters, metadataFields });
80:     query.pipe(
81:       `STATS failure = COUNT(*) WHERE TO_STRING(${EVENT_OUTCOME}) == "failure" OR TO_STRING(${STATUS_CODE}) == "Error", all = COUNT(*) BY timestamp = BUCKET(${AT_TIMESTAMP}, 100, ?_tstart, ?_tend)`
82:     );
83:     query.pipe('EVAL error_rate = TO_DOUBLE(failure) / all');
84:     query.pipe('KEEP timestamp, error_rate');
85:     query.pipe('SORT timestamp');
86: 
87:     return {
88:       id: 'error_rate',
89:       title: i18n.translate('metricsExperience.grid.error_rate.label', {
90:         defaultMessage: 'Error Rate',
91:       }),
92:       color: chartPalette[6],
93:       unit: 'percent',
94:       seriesType: 'line',
95:       esqlQuery: `${UNMAPPED_FIELDS_NULLIFY_SET_COMMAND} ${query.print('basic')}`,
96:     };
97:   } catch (error) {
98:     return null;
99:   }
100: }
