102: export function getLatencyChart({
103:   indexes,
104:   filters,
105:   metadataFields,
106: }: {
107:   indexes: string;
108:   filters: string[];
109:   metadataFields: string[];
110: }): TraceChart | null {
111:   try {
112:     const query = getBaseTraceQuery({ indexes, filters, metadataFields });
113:     // apm duration is in us
114:     query.pipe(
115:       `EVAL duration_ms_ecs = CASE(${TRANSACTION_DURATION} IS NOT NULL, TO_DOUBLE(${TRANSACTION_DURATION})/1000, ${SPAN_DURATION} IS NOT NULL, TO_DOUBLE(${SPAN_DURATION})/1000, null)`
116:     );
117:     // otel duration is in ns
118:     query.pipe(`EVAL duration_ms_otel = ROUND(${DURATION})/1000/1000`);
119:     // need to convert both to the same type to make sure the COALESCE works
120:     query.pipe('EVAL duration_ms = COALESCE(TO_LONG(duration_ms_ecs), TO_LONG(duration_ms_otel))');
121:     query.pipe(`STATS AVG(duration_ms) BY BUCKET(${AT_TIMESTAMP}, 100, ?_tstart, ?_tend)`);
122: 
123:     return {
124:       id: 'latency',
125:       title: i18n.translate('metricsExperience.grid.latency.label', {
126:         defaultMessage: 'Latency',
127:       }),
128:       color: chartPalette[2],
129:       unit: 'ms',
130:       seriesType: 'line',
131:       esqlQuery: `${UNMAPPED_FIELDS_NULLIFY_SET_COMMAND} ${query.print('basic')}`,
132:     };
133:   } catch (error) {
134:     return null;
135:   }
136: }
